        Command::new("git")
            .arg("-C")
            .arg(&repo)
            .args([
                "log",
                "--first-parent",
                "--merges",
                "--format=%H",
                "c8524c2..mission/observatory-v1",
            ])
            .output()
            .unwrap()
            .stdout,
    )
    .unwrap();
    println!("-- git log --first-parent --merges --format=%H c8524c2..{branch}\n{range}");
